import { test } from '@playwright/test';

test('diag: find overflow culprits at 390px', async ({ page }) => {
  test.slow();
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('/');

  const measure = () =>
    page.evaluate(() => {
      const cw = document.documentElement.clientWidth;
      const sw = document.documentElement.scrollWidth;
      const offenders = [];
      for (const el of document.querySelectorAll('body *')) {
        const r = el.getBoundingClientRect();
        if (r.width > 0 && (r.right > cw + 1 || r.left < -1)) {
          offenders.push({
            tag: el.tagName.toLowerCase(),
            cls: (el.className || '').toString().slice(0, 80),
            left: Math.round(r.left),
            right: Math.round(r.right),
            width: Math.round(r.width),
            overflowPx: Math.max(0, Math.round(r.right - cw)),
          });
        }
      }
      offenders.sort((a, b) => a.width - b.width);
      return { cw, sw, offenders };
    });

  const before = await measure();
  // Nhắc lại đúng thao tác của test mobile: mở sidebar, chọn nhóm, đo lại.
  await page.locator('button.sidebar-toggle').click();
  await page.locator('.sidebar-item').first().click();
  const after = await measure();

  console.log('BEFORE', JSON.stringify(before, null, 2));
  console.log('AFTER', JSON.stringify(after, null, 2));
});

